qs.append({"q":"The Morley-Minto Reforms were formally enacted through which legislation?","o":["Indian Councils Act, 1909","Government of India Act, 1919","Indian Councils Act, 1892","Government of India Act, 1935"],"a":0,"e":"The Morley-Minto Reforms translated into the Indian Councils Act of 1909."})

qs.append({"q":"Which of the following was the most detrimental feature of the Morley-Minto Reforms (Indian Councils Act, 1909), from the nationalist perspective?","o":["Introduction of separate electorates for Muslims","Increase in the number of elected members in legislative councils","Permission for legislatures to ask questions and supplementaries","Appointment of Satyendra Sinha to the viceroy's executive council"],"a":0,"e":"The introduction of separate electorates for Muslims is considered the most damaging provision, as it institutionalised communal division in Indian political representation."})

