qs.append({"q":"Regarding the budget provisions under the Indian Councils Act of 1909, legislatures were permitted to:","o":["Vote on separate items of the budget, though the budget as a whole could not be voted upon","Vote upon and amend the entire budget freely","Reject the budget entirely if a majority so wished","Have no role whatsoever in budget matters"],"a":0,"e":"The 1909 reforms allowed legislatures to vote on separate items within the budget, but the budget as a whole remained outside their voting power — a significant limitation."})

